mapper.select:
SELECT * FROM com_sales_order
WHERE tenant_id = #{query.tenantId}
  AND source_system = #{query.sourceSystem}
  AND source_record_key = #{query.sourceRecordKey}
  AND deleted = 0
FOR UPDATE

SELECT o.* FROM com_sales_order o
WHERE o.tenant_id = #{query.tenantId}
  AND o.deleted = 0


  AND CAST(o.company_code AS BINARY) = CAST(#{query.companyCode} AS BINARY)


  AND o.order_no LIKE CONCAT('%', #{query.orderNo}, '%')


  AND o.order_type = #{query.orderType}


  AND (o.customer_code LIKE CONCAT('%', #{query.customerKeyword}, '%')
    OR o.customer_name LIKE CONCAT('%', #{query.customerKeyword}, '%'))


  AND o.status = #{query.status}

ORDER BY o.order_no, o.id
LIMIT #{query.offset}, #{query.limit}

SELECT o.* FROM com_sales_order o
WHERE o.tenant_id = #{query.tenantId} AND o.deleted = 0


  AND (o.order_no > #{query.afterCode}
    OR (o.order_no = #{query.afterCode} AND o.id > #{query.afterId}))

ORDER BY o.order_no, o.id
LIMIT #{query.limit}
